-- Read-only verification after 023_event_participation.sql.
select table_name,column_name,data_type from information_schema.columns where table_schema='public' and ((table_name='schedules' and column_name in ('event_kind','event_registration_locked')) or (table_name='schedule_participations' and column_name in ('event_role','event_added_by'))) order by table_name,column_name;
select p.proname,has_function_privilege('authenticated',p.oid,'execute') as authenticated_can_execute,has_function_privilege('anon',p.oid,'execute') as anon_can_execute from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname='register_event_participation';
select c.relname,t.tgname from pg_trigger t join pg_class c on c.oid=t.tgrelid where not t.tgisinternal and t.tgname in ('runners_guard_event_schedule','runners_guard_event_participation','runners_after_event_participation') order by t.tgname;
select s.schedule_id,s.title,s.event_kind,s.capacity,s.event_registration_locked,s.registration_start_at,s.registration_end_at,count(p.participation_id) as active_count from public.schedules s left join public.schedule_participations p on p.schedule_id=s.schedule_id and p.user_id is not null and p.status in ('registered','completed') where s.schedule_type='event' and s.deleted_at is null group by s.schedule_id order by s.start_at;
-- Existing events with no capacity or opening date need operator configuration.
select schedule_id,title,event_kind,capacity,registration_start_at from public.schedules where schedule_type='event' and deleted_at is null and ((event_kind='gathering' and capacity is null) or registration_start_at is null);
